"""Publish pinned, unmodified SO101 follower print files; no network or fabrication."""
from pathlib import Path
import hashlib,json,shutil
ROOT=Path(__file__).resolve().parents[1]
src=ROOT/'assets-source/SO-ARM100'
out=ROOT/'public/robots/so101/build-kit'
out.mkdir(parents=True,exist_ok=True)
assert json.loads((ROOT/'public/robots/so101/provenance.json').read_text())['commit'] == 'a758567c3978dfeefe282ede0500085a48fe8f78'
assert 'Apache License' in (src/'LICENSE').read_text()
commit='a758567c3978dfeefe282ede0500085a48fe8f78'
base=f'https://github.com/TheRobotStudio/SO-ARM100/blob/{commit}/'
files=[]
def publish(path,name=None):
    dest=name or Path(path).name
    shutil.copyfile(src/path,out/dest)
    b=(out/dest).read_bytes()
    files.append(dict(file=dest,sourcePath=path,sourceUrl=base+path,license='Apache-2.0',licenseEvidence=base+'LICENSE',sha256=hashlib.sha256(b).hexdigest(),bytes=len(b),modified=False))
    return '/robots/so101/build-kit/'+dest
parts=['Base_motor_holder_SO101','Base_SO101','Motor_holder_SO101_Base','Motor_holder_SO101_Wrist','Under_arm_SO101','Upper_arm_SO101','Rotation_Pitch_SO101','Wrist_Roll_Pitch_SO101','WaveShare_Mounting_Plate_SO101','Moving_Jaw_SO101','Wrist_Roll_Follower_SO101']
rows=[]
for name in parts:
    path='STL/SO101/Individual/'+name+'.stl'
    rows.append(dict(id=name,name=name,category='printed',quantity=1,unit='piece',note='One follower; shared-part quantity derived from 3DPRINT.md (two per leader/follower pair). Waveshare board variant only.',source=base+'README.md#step-4-print-the-parts',download=publish(path)))
for id,name,n,unit,note in [
('servo','STS3215 7.4V, 1/345 (C001)',6,'piece','Baseline follower only. 12V alternative requires matching power supply; never mix.'),
('board','Waveshare motor control board',1,'piece','Use matching Waveshare printed mounting plate; check connector and board revision.'),
('usb','USB-C cable (2 pcs pack)',1,'pack','Upstream shopping unit is one two-cable pack, not two required connections. Confirm data capability.'),
('power','Power supply',1,'piece','Baseline source references 5V supply for 7.4V servos. Verify actual motor, polarity, current and connector before power. 12V alternative: 12V 5A+ per source.'),
('clamp','Table clamps (2 pcs pack)',1,'pack','Two physical clamps in one source pack.'),
('tools','Screwdriver set',1,'set','Phillips #0 and #1 recommended.'),
('fasteners','Screws / horns / servo cables',None,'kit','Complete follower-only count not reconciled. Guide has ambiguous M2/M3 fastener wording. Verify kit contents and each official step; not purchase-ready.')]:
    rows.append(dict(id=id,name=name,category='hardware',quantity=n,unit=unit,note=note,source=base+'README.md#parts-for-one-follower-arm',download=None))
rows[-1]['source']='https://github.com/huggingface/lerobot/blob/e6ffde60312365c5452c46189a26872483943154/docs/source/so101.mdx#L225-L328'
for p in ['LICENSE','README.md','3DPRINT.md']:publish(p,'SOURCE-'+p)
data=dict(configuration='SO-101 follower / Waveshare / 7.4V STS3215 C001 baseline',commit=commit,repository='https://github.com/TheRobotStudio/SO-ARM100',rows=rows,files=files,limitations=['Not a certified or complete manufacturing package. No physical build or print validation performed.','No 3MF file verified. Simulation servo meshes and SO101 Assembly.stl are not printable procurement parts.','No torque, nozzle/bed temperature, tolerances or full fastener total verified.'],printSettings=[dict(parameter='Material',value='PLA+',source=base+'README.md#step-1-choose-a-printer'),dict(parameter='Nozzle / layer height',value='0.4 mm / 0.2 mm OR 0.6 mm / 0.4 mm',source=base+'README.md#step-1-choose-a-printer'),dict(parameter='Infill (local printing)',value='15%',source=base+'README.md#step-1-choose-a-printer'),dict(parameter='Infill (outsourced printing guide)',value='20% FDM, mm units; separate context, not a replacement for local profile',source=base+'3DPRINT.md'),dict(parameter='Supports',value='Source: supports everywhere; ignore slopes >45° to horizontal; none in horizontal-axis screw holes. Review slicer interpretation.',source=base+'README.md#step-2-set-up-the-printer'),dict(parameter='Fit check',value='Use upstream servo or Lego gauges before printing final parts; no physical fit validated here.',source=base+'README.md#step-3-check-printer-accuracy')])
(out/'manifest.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
(ROOT/'src/core/buildKitData.ts').write_text('// Generated by scripts/build-kit-so101.py from pinned upstream evidence.\nexport const so101BuildKit = '+json.dumps(data,ensure_ascii=False,indent=2)+' as const;\n')
print(f'Published {len(parts)} printable parts, {len(rows)} BOM rows; {sum(x["bytes"] for x in files)} bytes')
